# AI Office v2.4 Final Certification Release Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
if(-not(Test-Path -LiteralPath $Repository -PathType Container)){throw "AI Office repository not found."}
Set-Location $Repository
$Timestamp=Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory=Join-Path $Repository ("workspace\installer-backups\v2.4-final-"+$Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force|Out-Null
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)
    $Destination=Join-Path $Repository $RelativePath
    $Parent=Split-Path -Parent $Destination
    if($Parent -and -not(Test-Path -LiteralPath $Parent)){New-Item -ItemType Directory -Path $Parent -Force|Out-Null}
    if(Test-Path -LiteralPath $Destination){
        $BackupPath=Join-Path $BackupDirectory $RelativePath
        $BackupParent=Split-Path -Parent $BackupPath
        if($BackupParent -and -not(Test-Path -LiteralPath $BackupParent)){New-Item -ItemType Directory -Path $BackupParent -Force|Out-Null}
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }
    [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\discord-office\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Certify-AIOfficeDiscordMobileOperations.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Publish-AIOfficeDiscordMobileOperationsRelease.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Test-AIOfficeDiscordMobileOperations.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Update-AIOfficeV24Readme.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.4-Release-Notes.md" -Base64Content ""
$ScriptPaths=@(
"E:\AI\AI-Office\scripts\discord-office\Certify-AIOfficeDiscordMobileOperations.ps1",
"E:\AI\AI-Office\scripts\discord-office\Publish-AIOfficeDiscordMobileOperationsRelease.ps1",
"E:\AI\AI-Office\scripts\discord-office\Test-AIOfficeDiscordMobileOperations.ps1",
"E:\AI\AI-Office\scripts\discord-office\Update-AIOfficeV24Readme.ps1")
foreach($ScriptPath in $ScriptPaths){$Tokens=$null;$ParseErrors=$null;[System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors)|Out-Null;if($ParseErrors.Count-gt0){throw ("Syntax error in "+$ScriptPath+": "+(($ParseErrors|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.4 final certification and release tooling installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan